contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller will attempt to withdraw, recipient receives funds, depositAmount funds this test contract first
    function checkWithdraw(address caller, address recipient, uint256 depositAmount) public {
        // fund this test contract so it can forward value to c
        require(address(this).balance >= depositAmount);

        // record the owner as seen via public getter
        address recordedOwner = c.owner();

        // deposit Ether into c so withdrawAll has funds to transfer
        // send depositAmount from this contract to c using fallback payable
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // attempt to call withdrawAll as the provided caller using a low-level call to set msg.sender
        // prepare calldata for withdrawAll(address)
        bytes memory payload = abi.encodeWithSignature("withdrawAll(address)", recipient);
        // perform the call: this will succeed only if msg.sender == recordedOwner in original P
        // We capture whether it reverted or not to observe behavior
        (bool ok, ) = address(c).call(payload);

        // The invariant: withdrawAll succeeds iff the invoker is the recorded owner
        // So assert that (ok == (caller == recordedOwner)). However, we cannot change msg.sender when calling directly.
        // To make the verifier observe the difference between P and M, we use the fact that when this contract itself
        // calls withdrawAll, msg.sender == address(this). The distinguishing input is when caller == recordedOwner == address(this).
        // Require that the supplied caller equals address(this) to ensure the deciding call's sender matches the 'caller' parameter.
        require(caller == address(this));

        // Final assertion: call success should equal whether recordedOwner equals this contract (the actual caller)
        assert( ok == (recordedOwner == address(this)) );
    }

    // allow this contract to receive Ether for depositAmount
    receive() external payable {}
}

