        // GENERAL RULE (single assertion): for the correct contract, after owner's withdrawAll,
        // the contract balance is always zero. The mutant that ignores call success can leave funds
        // in the contract if the recipient reverts, so for some inputs address(c).balance > 0.
        // We assert that address(c).balance == 0 (the property the reference satisfies for ALL inputs)
        // This assertion will fail on the mutant for cases where the recipient reverts and funds remain.
        assertTrue(address(c).balance == 0);
    }
}

// adversarial helper: if willRevert is true it reverts in receive/fallback, otherwise it accepts funds
contract ReverterOrAcceptor {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) revert("revert accept");
    }
    fallback() external payable {
        if (shouldRevert) revert("revert fallback");
    }
}
